import {DEMO_DATE,SECTIONS,MATERIALS} from './data.mjs';
import {createState,clone,STORAGE_PREFIX,patientById,recordById,updateField,newEncounter,completeEncounter,importDemo,crmProjection,scheduleAppointment,moveRequest,markHandoff,storageEnvelope,readEnvelope,validClinical,validCRM,searchWorkspace,progress} from './model.mjs';
import {shiftDate,weekDates,weekLabel,periodAppointments,appointmentCount} from './calendar.mjs';
import {initialsText,ageText,esc,icon,avatar,badge,button,fmtDate,statusTone,empty,field,textField,matrix,orbit,topo,oct} from './ui.mjs';
const root=document.querySelector('#app'),dialog=document.querySelector('#dialog'),toast=document.querySelector('#toast');
const state=createState();
const ui={module:'clinic',page:'today',patientId:null,recordId:null,section:'overview',compareId:null,side:true,queueFilter:'all',patientQuery:'',registryQuery:'',registryFilter:'all',materialFilter:'all',materialQuery:'',crmStage:'all',scheduleDate:DEMO_DATE,scheduleView:'day',mobileQueue:false,wide:false,queueDate:DEMO_DATE,contextDrawer:false};
const revisions=new Map(),saved=new Map(),dirty=new Set(),files=new Map();
let toastTimer,storageWarning='',dialogFocus=null;
function loadState(){
  try{
    const theme=localStorage.getItem(`${STORAGE_PREFIX}.theme`);if(theme==='dark'||theme==='light')document.documentElement.dataset.theme=theme;
    for(const p of state.patients){const e=readEnvelope(localStorage.getItem(`${STORAGE_PREFIX}.clinical.${p.id}`));if(e){if(!validClinical(e.value,p.id))throw new Error('Локальная карта не прошла проверку формата.');state.records[p.id]=e.value.records;if(Array.isArray(e.value.tasks)&&e.value.tasks.every(t=>typeof t.id==='string'&&typeof t.text==='string'&&typeof t.done==='boolean'&&t.patientId===p.id)){state.tasks=state.tasks.filter(t=>t.patientId!==p.id).concat(e.value.tasks);}state.pins[p.id]=Array.isArray(e.value.pins)?e.value.pins.filter(pin=>SECTIONS.some(s=>s.id===pin.section)&&state.records[p.id].some(r=>r.id===pin.recordId)):[];revisions.set(p.id,e.revision);saved.set(p.id,JSON.stringify({records:state.records[p.id],pins:state.pins[p.id]}));}}
    const crm=readEnvelope(localStorage.getItem(`${STORAGE_PREFIX}.crm`));if(crm){if(!validCRM(crm.value,state.patients.map(p=>p.id)))throw new Error('Локальная CRM не прошла проверку формата.');state.crm=crm.value;revisions.set('crm',crm.revision);saved.set('crm',JSON.stringify(crm.value));}
  }catch(error){storageWarning=error.message;}
}
loadState();
function currentPatient(){return patientById(state,ui.patientId);}
function currentRecord(){return recordById(state,ui.patientId,ui.recordId);}
function clinicalValue(id){return {records:state.records[id],pins:state.pins[id]??[],tasks:state.tasks.filter(t=>t.patientId===id)};}
function notice(text){clearTimeout(toastTimer);toast.innerHTML=`${icon('check-circle')}<span>${esc(text)}</span><button data-toast-close aria-label="Закрыть уведомление">${icon('close')}</button>`;toast.hidden=false;toastTimer=setTimeout(()=>toast.hidden=true,6000);}
function saveDomain(domain,force=false){
  const key=`${STORAGE_PREFIX}.${domain==='crm'?'crm':`clinical.${domain}`}`;
  try{
    const observed=readEnvelope(localStorage.getItem(key));const seen=revisions.get(domain)??0;
    if(!force&&(observed?.revision??0)!==seen){showDialog('Копия изменилась в другой вкладке',`<p>Текущая работа осталась в этой вкладке. В локальном хранилище есть более новая копия. Заменять её следует только после проверки.</p><div class="dialog-actions">${button('Вернуться к работе','close-dialog')}${button('Заменить локальную копию','force-save','saved','primary',`data-domain="${esc(domain)}"`)}</div>`);return false;}
    const value=domain==='crm'?state.crm:clinicalValue(domain);const envelope=storageEnvelope(value,observed?.revision??0);localStorage.setItem(key,JSON.stringify(envelope));revisions.set(domain,envelope.revision);saved.set(domain,JSON.stringify(value));dirty.delete(domain);updateSaveIndicator();return true;
  }catch(error){notice(`Не удалось сохранить: ${error.message}. Работа осталась в этой вкладке.`);return false;}
}
function updateSaveIndicator(){const el=document.querySelector('[data-save-state]');if(el){const active=ui.module==='crm'?'crm':ui.patientId;el.innerHTML=dirty.has(active)?'<i class="dirty-dot"></i> Есть изменения':`${icon('check',14)} ${saved.has(active)?'Сохранено на устройстве':'Демо-запись'}`;}}
function setDirty(id){dirty.add(id);updateSaveIndicator();}
function navigate(next,replace=false){Object.assign(ui,next);ui.mobileQueue=false;ui.contextDrawer=false;render();const hash=`#/${ui.module}/${ui.page}${ui.page==='patient'?`/${ui.patientId}`:''}`;if(location.hash!==hash)history[replace?'replaceState':'pushState'](null,'',hash);document.querySelector('#main')?.scrollTo(0,0);document.querySelector('#main')?.focus({preventScroll:true});}
function openPatient(id,recordId=null){const p=patientById(state,id);if(!p)return;const r=recordId?recordById(state,id,recordId):state.records[id][0];navigate({module:'clinic',page:'patient',patientId:id,recordId:r?.id,section:'overview',compareId:null});}
function readRoute(){const [,module,page,id]=location.hash.split('/');if(!['clinic','crm'].includes(module))return;if(module==='clinic'&&page==='patient'&&patientById(state,id)){ui.module=module;ui.page=page;ui.patientId=id;ui.recordId=state.records[id][0].id;}else if((module==='clinic'?['today','patients','materials']:['today','schedule','requests','handoff']).includes(page)){ui.module=module;ui.page=page;}}
readRoute();
function navTabs(){const tabs=ui.module==='clinic'?[['today','Рабочий день','grid'],['patients','Пациенты','people'],['materials','Материалы','folder']]:[['today','Сегодня','grid'],['schedule','Расписание','calendar'],['requests','Обращения','chat'],['handoff','Выдача и контроль','box']];return tabs.map(([id,title,ic])=>button(esc(title),'page',ic,ui.page===id?'active':'',`data-page="${id}" aria-current="${ui.page===id?'page':'false'}"`)).join('');}
function header(){return `<header class="topbar"><a class="brand" href="#/clinic/today" data-action="home" aria-label="Dr. Mate — рабочий день"><img src="assets/mark.svg" alt=""/><span class="brand-word">Dr. Mate<span>®</span></span></a><div class="module-switch" aria-label="Модуль">${button('Clinic','module','eye',ui.module==='clinic'?'active':'',`data-module="clinic" aria-pressed="${ui.module==='clinic'}"`)}${button('CRM','module','people',ui.module==='crm'?'active':'',`data-module="crm" aria-pressed="${ui.module==='crm'}"`)}</div><div class="top-spacer"></div><button class="global-search" data-action="search" aria-label="Поиск по рабочему пространству">${icon('search')}<span>Найти в пространстве</span><kbd>⌘ K</kbd></button><span class="demo-label"><i></i> Демо-пространство</span><button class="icon-btn theme-btn" data-action="theme" aria-label="${document.documentElement.dataset.theme==='dark'?'Светлая тема':'Тёмная тема'}">${icon(document.documentElement.dataset.theme==='dark'?'sun':'moon')}</button><button class="icon-btn help-btn" data-action="about" aria-label="О прототипе">${icon('info')}</button><button class="user-button" data-action="profile" aria-label="Рабочий профиль">АМ</button></header><div class="subbar"><div class="workspace-label"><span class="module-dot" data-tone="${ui.module==='clinic'?'mint':'blue'}"></span><span>${ui.module==='clinic'?'Пространство врача':'Пространство администратора'}</span></div><nav class="view-tabs" aria-label="Представления модуля">${navTabs()}</nav><button class="icon-btn queue-toggle" data-action="mobile-queue" aria-label="Открыть очередь">${icon('menu')}</button><button class="context-toggle ${!ui.side?'off':''}" data-action="toggle-side" aria-label="Рабочий контекст" aria-expanded="${window.innerWidth<=1000?ui.contextDrawer:ui.side}">${icon('sliders',16)}<span>Контекст</span></button></div>`;}
function queue(){
  const q=ui.patientQuery.toLocaleLowerCase('ru');const today=state.crm.appointments.filter(a=>a.date===ui.queueDate&&a.status!=='Отменён').sort((a,b)=>a.time.localeCompare(b.time));
  const items=today.filter(a=>{const p=patientById(state,a.patientId);return (ui.queueFilter==='all'||(ui.queueFilter==='waiting'&&['Ожидает','В кабинете'].includes(a.status))||(ui.queueFilter==='upcoming'&&a.time>='11:00'))&&`${p.name} ${p.id}`.toLocaleLowerCase('ru').includes(q);});
  return `<aside tabindex="-1" class="left-panel ${ui.mobileQueue?'mobile-open':''}" aria-label="Очередь приёмов"><div class="left-heading"><div><span class="eyebrow">ДЕМО-РАСПИСАНИЕ</span><h2>${new Date(`${ui.queueDate}T12:00:00`).toLocaleDateString('ru-RU',{day:'numeric',month:'long'})} <span>2026</span></h2></div>${button('','appointment','plus','icon-btn',`aria-label="Добавить запись"`)}</div><div class="day-nav">${button('','day-prev','left','icon-btn',`aria-label="Предыдущий день"`)}<span>${ui.queueDate===DEMO_DATE?'Сегодня':fmtDate(ui.queueDate)}<span class="day-count">${today.length} приёмов</span></span>${button('','day-next','right','icon-btn',`aria-label="Следующий день"`)}</div><label class="side-search">${icon('search',16)}<input data-queue-search type="search" placeholder="Найти пациента" aria-label="Найти пациента в очереди" value="${esc(ui.patientQuery)}"/></label><div class="segmented queue-segments" aria-label="Фильтр очереди">${[['all','Все'],['waiting','Ожидают'],['upcoming','Позже']].map(([id,title])=>button(title,'queue-filter','',ui.queueFilter===id?'active':'',`data-filter="${id}" aria-pressed="${ui.queueFilter===id}"`)).join('')}</div><div class="patient-queue" data-queue-list>${queueItems(items)}</div><div class="sidebar-bottom"><button class="resource-link" data-action="knowledge">${icon('book')}<span><b>Knowledge</b><small>Справочник под рукой</small></span>${icon('external',14)}</button><button class="resource-link" data-action="orders">${icon('box')}<span><b>Flux · Orders</b><small>Заказы и их основания</small></span>${icon('external',14)}</button><div class="sidebar-note">${icon('shield',14)}<span>Все пациенты и данные вымышленные</span></div></div></aside>`;
}
function queueItems(items){return items.length?items.map(a=>{const p=patientById(state,a.patientId),selected=ui.page==='patient'&&ui.patientId===p.id;return `<button class="queue-person ${selected?'selected':''}" data-action="patient" data-id="${p.id}" aria-label="Открыть карту: ${esc(p.name)}" aria-pressed="${selected}"><div class="queue-time"><span>${esc(a.time)}</span><i data-tone="${statusTone(a.status)}"></i></div><div class="queue-person-content">${avatar(p,'small')}<span><b>${esc(p.name)}</b><small>${esc(a.kind)}</small></span></div><div class="queue-meta"><span>${ageText(p.age)} · ${a.duration} мин</span><span data-tone="${statusTone(a.status)}">${esc(a.status)}</span></div></button>`;}).join(''):empty('Никого не найдено','Измените поиск или фильтр.');}
function rightPanel(){
  const p=currentPatient(),r=currentRecord(),isPatient=ui.module==='clinic'&&ui.page==='patient';
  if(ui.module==='crm')return crmContext();
  const tasks=state.tasks.filter(t=>!isPatient||t.patientId===p?.id);
  return `<aside tabindex="-1" class="right-panel" aria-label="Рабочий контекст" ${ui.side?'':'hidden'}><div class="context-heading"><span>${icon('sliders',16)} Рабочий контекст</span>${button('','toggle-side','close','icon-btn',`aria-label="Скрыть рабочий контекст"`)}</div>${isPatient?`<section class="context-section"><div class="section-label">ПАЦИЕНТ</div><div class="context-profile">${avatar(p)}<div><h3>${esc(p.name)}</h3><p>${ageText(p.age)} · ${p.id.toUpperCase()}</p></div></div><div class="context-purpose"><span>${icon('focus',16)} Цель визита</span><p>${esc(p.goal)}</p></div></section>`:`<section class="context-section context-greeting"><span class="eyebrow">РАБОЧЕЕ ПРОСТРАНСТВО</span><h3>Всё под рукой.</h3><p>Задачи, материалы и важные детали — рядом с вашей работой.</p></section>`}<section class="context-section"><div class="context-section-title"><h3>${icon('check-circle',16)} ${isPatient?'На этом визите':'Задачи дня'}</h3>${button('','new-task','plus','icon-btn',`aria-label="Добавить задачу"`)}</div><div class="tasks">${tasks.length?tasks.map(t=>`<label class="task ${t.done?'done':''}"><input type="checkbox" data-task="${t.id}" ${t.done?'checked':''}/><span>${esc(t.text)}<small>${esc(t.time)}${!isPatient?` · ${esc(patientById(state,t.patientId)?.name??'Без пациента')}`:''}</small></span></label>`).join(''):'<p class="muted">Задач пока нет. Добавьте следующий шаг.</p>'}</div></section>${isPatient?pinsPanel(p,r):`<section class="context-section"><div class="context-section-title"><h3>${icon('pin',16)} Быстрый доступ</h3></div><button class="context-link" data-action="patient" data-id="dm-0148"><span><b>Карта Марии Соколовой</b><small>Текущий приём · 09:30</small></span>${icon('arrow',16)}</button><button class="context-link" data-action="materials"><span><b>Последние материалы</b><small>Учебные схемы и документы</small></span>${icon('arrow',16)}</button></section>`}<section class="context-section"><div class="context-section-title"><h3>${icon('folder',16)} Файлы под рукой</h3><span class="micro">${files.size} / 6</span></div><div class="file-slots">${Array.from({length:6},(_,i)=>{const f=files.get(i);return `<button class="file-slot ${f?'has-file':''}" data-action="file" data-slot="${i}" aria-label="${f?`Открыть файл ${esc(f.name)}`:`Закрепить файл в слоте ${i+1}`}">${icon(f?'document':'plus',16)}<span>${f?esc(f.name):`Слот ${String(i+1).padStart(2,'0')}`}</span></button>`;}).join('')}</div><p class="fine-print">Выбранные файлы доступны только в этой вкладке.</p></section><section class="context-section context-foot"><span class="section-label">СВЯЗАННЫЕ МОДУЛИ</span><button class="module-bridge" data-action="module" data-module="crm">${icon('people')}<span>Открыть пространство CRM</span>${icon('arrow',15)}</button></section></aside>`;
}
function pinsPanel(p,r){const pins=state.pins[p.id]??[];return `<section class="context-section"><div class="context-section-title"><h3>${icon('pin',16)} Закреплено</h3><span class="micro">${pins.length}</span></div>${pins.length?pins.map(pin=>{const source=recordById(state,p.id,pin.recordId),s=SECTIONS.find(s=>s.id===pin.section);if(!source||!s)return '';return `<article class="pinned-card" data-tone="${s.tone}"><div class="pin-head"><b>${icon(s.icon,14)} ${esc(s.short)}</b>${button('','unpin','close','icon-btn',`data-key="${pin.recordId}:${pin.section}" aria-label="Открепить ${esc(s.title)}"`)}</div><small>${fmtDate(source.date)} · ${source.status==='completed'?'Завершён':'Черновик'}</small>${sectionSummary(s.id,source,true)}<button class="text-btn" data-action="pin-open" data-record="${source.id}" data-section="${s.id}">Открыть источник ${icon('external',13)}</button></article>`;}).join(''):`<div class="pin-placeholder">${icon('pin',22)}<p>Закрепите карточку, чтобы держать её рядом.</p></div>`}</section>`;}
function pageHeading(eyebrow,title,description='',actions=''){if(ui.module==='crm')actions=button('Сохранить','save-crm','saved')+actions;return `<div class="page-heading"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1>${description?`<p>${description}</p>`:''}</div><div class="heading-actions">${actions}</div></div>`;}
function todayPage(){
  const appointments=state.crm.appointments.filter(a=>a.date===DEMO_DATE&&a.status!=='Отменён').sort((a,b)=>a.time.localeCompare(b.time));
  const next=appointments.find(a=>a.status==='В кабинете')??appointments[0];const p=next?patientById(state,next.patientId):null;
  const unfinished=Object.values(state.records).flat().filter(r=>r.status==='draft'&&(r.complaint||r.findings));
  const tasks=state.tasks.filter(t=>!t.done);
  return `${pageHeading('CLINIC / РАБОЧИЙ ДЕНЬ','Рабочий день','Четверг, 8 октября · ваш день в одном пространстве',button('Новый приём','new-visit','plus','primary'))}<section class="desk-hero"><div class="hero-content"><div class="hero-kicker"><span class="live-dot"></span> ${next?.status==='В кабинете'?'СЕЙЧАС НА ПРИЁМЕ':'БЛИЖАЙШИЙ ПРИЁМ'}</div><div class="hero-patient">${p?avatar(p):''}<div><h2>${esc(p?.name??'Свободное время')}</h2><p>${esc(next?.kind??'Запланируйте новый приём')} ${p?`· ${ageText(p.age)}`:''}</p></div></div><p class="hero-purpose">${esc(p?.goal??'Все записи на сегодня завершены.')}</p><div class="hero-actions">${p?button('Открыть карту','patient','arrow','primary',`data-id="${p.id}"`):button('Записать пациента','appointment','plus','primary')}<span>${icon('clock',15)} ${esc(next?.time??'')} ${next?`— ${addMinutes(next.time,next.duration)}`:''}</span></div></div><div class="hero-art">${orbit('desk')}<span class="art-label"><i></i> В ФОКУСЕ · ЧЕЛОВЕК</span></div></section><div class="desk-stats"><button data-action="schedule"><span>${icon('calendar')} Приёмов сегодня</span><strong>${appointments.length}<small> ${appointments.reduce((sum,a)=>sum+a.duration,0)} минут в расписании</small></strong></button><button data-action="unfinished"><span>${icon('document')} Незавершённые записи</span><strong>${unfinished.length}<small>вернуться к итогам</small></strong></button><button data-action="show-tasks"><span>${icon('check-circle')} Задачи врача</span><strong>${tasks.length}<small>на сегодня</small></strong></button></div><div class="desk-columns"><section class="surface schedule-surface"><div class="surface-heading"><h2>${icon('calendar')} Дальше по расписанию</h2>${button('Весь день','schedule','arrow','text-btn')}</div>${appointments.filter(a=>a!==next).slice(0,4).map(a=>{const p=patientById(state,a.patientId);return `<button class="appointment-row" data-action="patient" data-id="${p.id}"><time>${a.time}</time>${avatar(p,'small')}<span><b>${esc(p.name)}</b><small>${esc(a.kind)} · ${a.duration} мин</small></span>${badge(a.status,statusTone(a.status),true)}${icon('right',16)}</button>`;}).join('')||empty('День свободен','Добавьте запись в расписание.','calendar')}</section><section class="surface attention-surface"><div class="surface-heading"><h2>${icon('focus')} Внимание сегодня</h2><span class="count">2</span></div><button class="attention-item" data-action="patient" data-id="dm-0148"><span class="attention-icon" data-tone="violet">${icon('lens')}</span><span><b>Задача новой пары</b><p>Проверить ожидания на контрольном осмотре</p><small>Мария Соколова · версия 2</small></span>${icon('arrow',16)}</button><button class="attention-item" data-action="module" data-module="crm"><span class="attention-icon" data-tone="amber">${icon('calendar')}</span><span><b>Подтверждение визита</b><p>Уточнить запись на вторую половину дня</p><small>Анна Ким · 14:30</small></span>${icon('arrow',16)}</button><div class="quiet-note">${icon('info',16)}<span>Клинические решения остаются за врачом. Здесь — организация рабочего дня.</span></div></section></div><section class="recent-section"><div class="section-heading"><h2>Последние материалы</h2>${button('Все материалы','materials','arrow','text-btn')}</div><div class="materials-grid">${MATERIALS.slice(0,3).map(m=>materialTile(m)).join('')}</div></section>`;
}
function addMinutes(time,n){const v=Number(time.slice(0,2))*60+Number(time.slice(3))+n;return `${String(Math.floor(v/60)).padStart(2,'0')}:${String(v%60).padStart(2,'0')}`;}
function materialTile(m){return `<button class="material-tile" data-action="material" data-id="${m.id}"><div class="material-art" data-tone="${m.tone}">${m.id==='topography'?topo(`tile-${m.id}`,true):m.id==='oct'?oct():`<div class="document-art">${icon('document',38)}<i></i><i></i><i></i></div>`}<span class="material-tag">${esc(m.kind)}</span></div><div class="material-info"><b>${esc(m.title)}</b><span>${m.date} ${m.patientId?`· ${esc(patientById(state,m.patientId)?.name??'')}`:''}</span>${icon('external',15)}</div></button>`;}
function patientPage(){
  const p=currentPatient(),r=currentRecord();if(!p||!r)return empty('Карта не найдена','Выберите пациента в очереди.','people');
  const pr=progress(r);const completed=Object.values(pr).filter(Boolean).length;
  return `<div class="patient-breadcrumb"><button class="text-btn" data-action="page" data-page="today">Рабочий день</button>${icon('right',12)}<span>Карта пациента</span><span class="record-status" data-save-state></span></div><header class="patient-header">${avatar(p,'large')}<div class="patient-title"><div class="patient-name"><h1>${esc(p.name)}</h1>${badge(`${ageText(p.age)}`)}<span class="patient-id">${p.id.toUpperCase()}</span></div><p>${esc(p.goal)}</p></div><div class="patient-actions">${button('Сохранить','save','saved','',`aria-label="Сохранить карту на устройстве"`)}${button(r.status==='draft'?'Завершить приём':'Новый приём',r.status==='draft'?'complete':'patient-new','check','primary')}</div></header><div class="record-toolbar"><label class="record-select">${icon('calendar',16)}<select data-record-select aria-label="Осмотр">${state.records[p.id].map(rec=>`<option value="${rec.id}" ${rec.id===r.id?'selected':''}>${fmtDate(rec.date)} · ${esc(rec.title)}${rec.status==='draft'?' · Черновик':''}</option>`).join('')}</select></label>${badge(r.status==='draft'?'Черновик':'Завершён · только чтение',r.status==='draft'?'amber':'mint',true)}<div class="toolbar-spacer"></div>${button('История','history','history','text-btn')}${button(ui.compareId?'Закрыть сравнение':'Сравнить','compare','compare',ui.compareId?'active':'',state.records[p.id].length<2?'disabled title="Для сравнения нужен второй визит"':'')}${button('','wide','expand',`icon-btn ${ui.wide?'active':''}`,`aria-label="${ui.wide?'Вернуть боковые панели':'Расширить рабочую область'}" aria-pressed="${ui.wide}"`)}</div><nav class="clinical-tabs" aria-label="Разделы приёма" role="tablist"><button data-action="section" data-section="overview" id="section-tab-overview" role="tab" aria-controls="section-panel" aria-selected="${ui.section==='overview'}" tabindex="${ui.section==='overview'?0:-1}" class="${ui.section==='overview'?'active':''}" title="Разделы с введёнными данными; не оценка полноты осмотра" aria-current="${ui.section==='overview'?'page':'false'}">${icon('grid',16)}Обзор<span>${completed}/6</span></button>${SECTIONS.map(s=>`<button data-action="section" data-section="${s.id}" id="section-tab-${s.id}" role="tab" aria-controls="section-panel" aria-selected="${ui.section===s.id}" tabindex="${ui.section===s.id?0:-1}" data-tone="${s.tone}" class="${ui.section===s.id?'active':''}" aria-current="${ui.section===s.id?'page':'false'}">${icon(s.icon,16)}${s.short}<i class="step-dot ${pr[s.id]?'filled':''}"></i></button>`).join('')}</nav>${r.status==='completed'?'<div class="readonly-banner">'+icon('shield',16)+'<span>Завершённая учебная запись сохранена как история. Новый приём начинается с пустых наблюдений.</span></div>':''}<div class="clinical-workspace ${ui.compareId?'is-comparing':''}"><div class="clinical-primary" id="section-panel" role="tabpanel" aria-labelledby="section-tab-${ui.section}">${ui.compareId?`<div class="compare-strip">${icon('compare',16)}<span>Сравнение с ${fmtDate(recordById(state,p.id,ui.compareId)?.date)} · история</span>${button('К сравнению','compare-focus','down','text-btn')}</div>`:''}${ui.section==='overview'?`<div class="visit-intent">${icon('focus',20)}<div><span class="eyebrow">КОНТЕКСТ ТЕКУЩЕГО ВИЗИТА</span><p>${esc(r.context||'Условия исследования ещё не указаны')}</p></div>${button('Уточнить','section','', 'text-btn',`data-section="interview"`)}</div><div class="clinical-cards">${SECTIONS.map(s=>clinicalCard(s,r)).join('')}</div>`:expandedSection(SECTIONS.find(s=>s.id===ui.section),r)}${ui.section==='overview'?`<div class="visit-footer"><span>${icon('document',16)} Учебный приём · данные изолированы от других пациентов</span>${button('К итогу приёма','section','arrow','text-btn',`data-section="conclusion"`)}</div>`:''}</div>${ui.compareId?comparisonPanel(p,r):''}</div>`;
}
function clinicalCard(s,r){const has=progress(r)[s.id],pins=state.pins[r.patientId]??[],pinned=pins.some(p=>p.recordId===r.id&&p.section===s.id);return `<section class="clinical-card" data-tone="${s.tone}"><div class="clinical-card-head"><h2><span class="subject-icon">${icon(s.icon,17)}</span>${esc(s.title)}</h2><div>${button('','pin', 'pin',`icon-btn ${pinned?'pinned':''}`,`data-section="${s.id}" aria-label="${pinned?'Открепить':'Закрепить'} ${esc(s.title)}" aria-pressed="${pinned}"`)}${button('','section','expand','icon-btn',`data-section="${s.id}" aria-label="Раскрыть ${esc(s.title)}"`)}</div></div><div class="clinical-card-body">${sectionSummary(s.id,r)}<div class="card-bottom"><span>${has?'Внесено в демо-запись':'Нет данных'}</span><button class="text-btn" data-action="section" data-section="${s.id}">${r.status==='draft'?(has?'Подробнее':'Заполнить'):'Открыть'} ${icon('arrow',13)}</button></div></div></section>`;}
function sectionSummary(id,r,small=false){switch(id){
  case 'interview':return `<p class="summary-text">${esc(r.complaint||'Жалобы ещё не записаны.')}</p>${!small?`<div class="summary-detail"><span>Анамнез</span><p>${esc(r.history||'Не указан')}</p></div>`:''}`;
  case 'refraction':return matrix(r,'refraction',false,small?[['sph','Sph','D'],['cyl','Cyl','D'],['va','Vis','']]:undefined)+(!small?`<div class="binocular-line"><span>Бинокулярная Vis</span><b>${esc(r.refraction.OU.va||'Не измерена')}</b></div><div class="source-note">${icon('document',12)} ${fmtDate(r.date)} · ${esc(r.source)}</div>`:'');
  case 'exam':return `<p class="summary-text">${esc(r.exam||'Наблюдения осмотра ещё не внесены.')}</p>${!small&&r.patientId==='dm-0148'?`<button class="inline-material" data-action="material" data-id="topography">${icon('scan',14)} Топография · учебная схема ${icon('external',12)}</button>`:''}`;
  case 'lenses':return `<div class="lens-title">${icon('lens',small?20:28)}<span><b>${esc(r.lenses.model||'Пара не указана')}</b><small>${r.lenses.model?'Контекст коррекции · демо':'Без автоматического подбора'}</small></span></div>${!small?`<div class="lens-values"><span>OD <b>${esc(r.lenses.OD.power||'—')}</b></span><span>OS <b>${esc(r.lenses.OS.power||'—')}</b></span><span>Оценка <b>${r.lenses.OD.fit||r.lenses.OS.fit?'Записана':'Ожидается'}</b></span></div>`:''}`;
  case 'binocular':return `<div class="binocular-status">${icon('focus',small?18:27)}<span>${esc(r.binocular.note||'Данные ещё не внесены.')}</span></div>${!small?`<div class="summary-detail"><span>Ближняя точка конвергенции</span><p>${esc(r.binocular.npc||'Не измерена')}</p></div>`:''}`;
  case 'conclusion':return `<p class="summary-text">${esc(r.decision||'Решение врача ещё не записано.')}</p>${!small?`<div class="summary-detail"><span>Следующий шаг</span><p>${esc(r.plan||'План пока не указан')}</p></div>`:''}`;
}return '';}
function expandedSection(s,r){if(!s)return '';const readOnly=r.status!=='draft',extra=readOnly?'readonly':'',pins=state.pins[r.patientId]??[],pinned=pins.some(p=>p.recordId===r.id&&p.section===s.id);return `<section class="expanded-section" data-tone="${s.tone}"><div class="expanded-heading"><div><span class="subject-icon">${icon(s.icon,22)}</span><div><span class="eyebrow">${fmtDate(r.date)} · ${r.status==='draft'?'ТЕКУЩИЙ ПРИЁМ':'ИСТОРИЧЕСКАЯ ЗАПИСЬ'}</span><h2>${esc(s.title)}</h2></div></div><div class="expanded-actions">${button(pinned?'Закреплено':'Закрепить','pin','pin',pinned?'pinned':'',`data-section="${s.id}" aria-pressed="${pinned}"`)}${button('Свернуть','section','up','',`data-section="overview"`)}</div></div><div class="expanded-body">${sectionForm(s.id,r,extra)}</div><div class="expanded-footer"><span>${icon('document',14)} ${esc(r.source)}</span>${button('К следующему разделу','next-section','arrow','text-btn')}</div></section>`;}
function sectionForm(id,r,ro){switch(id){
  case 'interview':return `<div class="form-grid two">${textField('Жалобы и цель обращения','complaint',r.complaint,'Что беспокоит пациента?',5,ro)}${textField('Анамнез','history',r.history,'Важные обстоятельства и предыдущее лечение',5,ro)}</div>${textField('Условия исследования','context',r.context,'Коррекция, режим ношения, время снятия линз…',3,ro)}<div class="form-note">${icon('info',16)}<span>Условия сохраняются в записи этого визита и помогают сравнивать исследования.</span></div>`;
  case 'refraction':return `<div class="form-section-heading"><div><h3>Манифестная рефракция</h3><p>Результат субъективного исследования на этом визите</p></div>${badge('Ручной ввод','mint')}</div>${matrix(r,'refraction',!ro)}<div class="binocular-editor">${field('Vis OU · бинокулярная','refraction.OU.va',r.refraction.OU.va,'text',`placeholder="Не измерена" ${ro}`)}<span>Измеряется отдельно. Не вычисляется из OD и OS.</span></div><div class="form-divider"></div><div class="form-section-heading"><div><h3>Авторефракция</h3><p>Сырые измерения прибора · отдельный источник</p></div>${!ro?button(r.imported?'Пакет загружен':'Демо-пакет','import','upload','',r.imported?'disabled':''):''}</div>${matrix(r,'auto',!ro,[['sph','Sph','D'],['cyl','Cyl','D'],['axis','Axis','°']])}<div class="form-note">${icon('link',16)}<span>Передача результата в Orders предполагает явное основание и версию исследования. Живая интеграция здесь не подключена.</span></div>`;
  case 'exam':return `${textField('Описание осмотра','exam',r.exam,'Наблюдения врача, качество измерений, ограничения',5,ro)}<div class="form-divider"></div><div class="form-section-heading"><div><h3>Кератометрия</h3><p>Исходные значения · диоптрии, ось в градусах, HVID в мм</p></div>${badge('Без пересчёта единиц','blue')}</div>${matrix(r,'keratometry',!ro,[['flat','K flat','D'],['steep','K steep','D'],['axis','Axis','°'],['hvid','HVID','мм']])}<div class="form-divider"></div><div class="form-section-heading"><h3>Материалы визита</h3>${button('Выбрать файл','attach-material','plus')}</div>${r.patientId==='dm-0148'?`<div class="materials-grid compact">${MATERIALS.filter(m=>m.patientId===r.patientId&&m.section==='exam').map(materialTile).join('')}</div>`:empty('Материалы не добавлены','Выберите локальный файл для просмотра в этой вкладке.','folder')}`;
  case 'lenses':return `${field('Пара или версия дизайна','lenses.model',r.lenses.model,'text',`placeholder="Название и версия" ${ro}`)}<div class="form-divider"></div><h3 class="form-subtitle">Записанные параметры пары</h3>${matrix(r,'lenses',!ro,[['power','Pwr','D'],['bc','BC','мм'],['dia','DIA','мм']])}<div class="form-grid two">${textField('Посадка OD','lenses.OD.fit',r.lenses.OD.fit,'Наблюдения правого глаза',3,ro)}${textField('Посадка OS','lenses.OS.fit',r.lenses.OS.fit,'Наблюдения левого глаза',3,ro)}</div>${r.patientId==='dm-0148'&&r.lenses.model==='Учебная пара A · версия 2'?`<section class="pair-intent"><div class="form-section-heading"><h3>${icon('focus')} Задача этой пары</h3>${badge('Замысел врача','violet')}</div><p>Улучшить комфорт к вечеру, сохранив записанную коррекцию. Это учебный замысел версии 2, а не рекомендация алгоритма.</p><div class="expectation"><span><b>Комфорт в конце дня</b><small>Оценить по ответу пациента</small></span><select data-expectation="comfort" aria-label="Оценка ожидания: комфорт" ${ro?'disabled':''}>${expectationOptions('comfort')}</select></div><div class="expectation"><span><b>Качество зрения</b><small>Сопоставить измерения с прошлым визитом</small></span><select data-expectation="vision" aria-label="Оценка ожидания: зрение" ${ro?'disabled':''}>${expectationOptions('vision')}</select></div></section>`:''}${textField('Комментарий и основания оценки','lenses.note',r.lenses.note,'Что подтверждено, что не оценено, на чём основан вывод',3,ro)}`;
  case 'binocular':return `<div class="form-note">${icon('focus',20)}<span>Записывайте измеренное и наблюдаемое. Пустое поле означает отсутствие данных.</span></div><div class="form-grid three">${field('Фория вдаль · призменные D','binocular.distance',r.binocular.distance,'text',`placeholder="Не измерена" ${ro}`)}${field('Фория вблизи · призменные D','binocular.near',r.binocular.near,'text',`placeholder="Не измерена" ${ro}`)}${field('БТК · см','binocular.npc',r.binocular.npc,'text',`placeholder="Не измерена" ${ro}`)}</div>${textField('Наблюдения и условия','binocular.note',r.binocular.note,'Метод, условия измерения, клинический комментарий',5,ro)}`;
  case 'conclusion':return `${textField('Наблюдения и основания','findings',r.findings,'Что установлено на визите и какие данные ограничены',4,ro)}${textField('Решение врача','decision',r.decision,'Сформулируйте итог визита',4,ro)}${textField('План и следующий шаг','plan',r.plan,'Что делать дальше и что проверить при следующем визите',4,ro)}<div class="form-grid two">${field('Дата следующего визита','followupDate',r.followupDate,'date',ro)}<div class="admin-handoff"><span>${icon('people')} Операционный шаг для CRM</span><p>Запись на следующий визит. Полное заключение остаётся в Clinic.</p>${button('Посмотреть CRM','module','arrow','text-btn',`data-module="crm"`)}</div></div>${!ro?`<div class="completion-box"><span>${icon('check-circle',23)}<span><b>Готовы закончить приём?</b><small>Проверьте решение и сохраните учебную запись.</small></span></span>${button('Завершить приём','complete','check','primary')}</div>`:''}`;
}return '';}
function expectationOptions(id){const value=currentRecord()?.expectations[id]??'Не оценено';return ['Не оценено','Подтвердилось','Частично подтвердилось','Не подтвердилось','Несопоставимо'].map(v=>`<option ${value===v?'selected':''}>${v}</option>`).join('');}
function comparisonPanel(p,current){const ref=recordById(state,p.id,ui.compareId);if(!ref)return '';return `<aside class="comparison-panel" tabindex="-1" aria-label="Сравнение с предыдущим визитом"><div class="comparison-head"><span>${icon('compare',16)} Открыто рядом</span>${button('','compare-close','close','icon-btn',`aria-label="Закрыть сравнение"`)}</div><div class="comparison-content"><span class="eyebrow">${ref.status==='completed'?'ИСТОРИЯ · ТОЛЬКО ЧТЕНИЕ':'ОПОРНЫЙ ЧЕРНОВИК · ТОЛЬКО ЧТЕНИЕ'}</span><h2>${fmtDate(ref.date)}</h2><label class="field"><span>Опорный визит</span><select data-comparison-select aria-label="Визит для сравнения">${state.records[p.id].filter(r=>r.id!==current.id).map(r=>`<option value="${r.id}" ${r.id===ref.id?'selected':''}>${fmtDate(r.date)} · ${esc(r.title)}</option>`).join('')}</select></label><div class="comparison-card" data-tone="mint"><h3>${icon('scan',16)} Рефракция</h3>${matrix(ref,'refraction',false,[['sph','Sph','D'],['cyl','Cyl','D'],['va','Vis','']])}<div class="binocular-line"><span>Vis OU</span><b>${esc(ref.refraction.OU.va||'Не измерена')}</b></div><div class="source-note">Исходный результат · ${fmtDate(ref.date)}</div></div><div class="comparison-card" data-tone="amber"><h3>${icon('chat',16)} Жалобы</h3><p>${esc(ref.complaint||'Нет записи')}</p></div><div class="comparison-card" data-tone="cyan"><h3>${icon('check-circle',16)} Решение врача</h3><p>${esc(ref.decision||'Не записано')}</p><small>${esc(ref.plan||'')}</small></div><div class="compare-note">${icon('info',15)}<p>Сравнение показывает исходные записи. Клинический вывод не вычисляется автоматически.</p></div>${button('К текущему визиту','current-focus','up','text-btn compare-return')}${button('Открыть визит основным','record-open','external','',`data-record="${ref.id}"`)}</div></aside>`;}
function patientsPage(){
  return `${pageHeading('CLINIC / РЕЕСТР','Пациенты','Карта, история визитов и контекст — в одном месте.',button('Новый приём','new-visit','plus','primary'))}<div class="registry-toolbar"><label class="local-search">${icon('search')}<input type="search" data-registry-search aria-label="Поиск в реестре пациентов" placeholder="Имя, номер карты, тип визита…" value="${esc(ui.registryQuery)}"/></label><div class="segmented">${[['all','Все пациенты'],['today','Сегодня'],['draft','С черновиками']].map(([id,title])=>button(title,'registry-filter','',ui.registryFilter===id?'active':'',`data-filter="${id}" aria-pressed="${ui.registryFilter===id}"`)).join('')}</div></div><section class="surface registry"><div class="registry-columns"><span>Пациент</span><span>Последний визит</span><span>Контекст</span><span>Карта</span></div><div data-registry-list>${registryItems()}</div></section><div class="registry-foot">${icon('shield',15)} Вымышленные пациенты · новые записи изолированы по карте</div>`;
}
function registryItems(){const q=ui.registryQuery.toLocaleLowerCase('ru');const patients=state.patients.filter(p=>`${p.name} ${p.id} ${p.kind}`.toLocaleLowerCase('ru').includes(q)&&(ui.registryFilter!=='draft'||state.records[p.id].some(r=>r.status==='draft'))&&(ui.registryFilter!=='today'||state.crm.appointments.some(a=>a.date===DEMO_DATE&&a.patientId===p.id&&a.status!=='Отменён')));return patients.length?patients.map(p=>`<button class="registry-row" data-action="patient" data-id="${p.id}"><span class="registry-person">${avatar(p)}<span><b>${esc(p.name)}</b><small>${ageText(p.age)} · ${p.id.toUpperCase()}</small></span></span><span>${p.last?fmtDate(p.last):'Первый визит'}<small>${state.records[p.id].length} ${state.records[p.id].length===1?'запись':'записи'}</small></span><span>${esc(p.kind)}<small>${esc(p.goal)}</small></span><span class="registry-open">Открыть ${icon('arrow',15)}</span></button>`).join(''):empty('Пациенты не найдены','Попробуйте другой запрос или фильтр.','people');}
function materialsPage(){return `${pageHeading('CLINIC / МАТЕРИАЛЫ','Материалы и источники','Исследования, документы и замыслы — с понятным происхождением.',button('Открыть локальный файл','attach-material','upload','primary'))}<div class="registry-toolbar"><label class="local-search">${icon('search')}<input data-material-search type="search" aria-label="Найти материал" placeholder="Название, пациент или тип…" value="${esc(ui.materialQuery)}"/></label><div class="segmented">${[['all','Все'],['scheme','Схемы'],['document','Документы']].map(([id,title])=>button(title,'material-filter','',ui.materialFilter===id?'active':'',`data-filter="${id}" aria-pressed="${ui.materialFilter===id}"`)).join('')}</div></div><div class="materials-grid gallery" data-material-list>${materialItems()}</div><div class="surface material-privacy">${icon('folder',24)}<div><h3>Ваш локальный материал остаётся в этой вкладке</h3><p>Можно открыть изображение, PDF или текст для просмотра. В прототипе файл не прикрепляется к истории и не отправляется на сервер.</p></div></div>`;}
function materialItems(){const q=ui.materialQuery.toLocaleLowerCase('ru');const items=MATERIALS.filter(m=>`${m.title} ${m.kind} ${patientById(state,m.patientId)?.name??''}`.toLocaleLowerCase('ru').includes(q)&&(ui.materialFilter==='all'||(ui.materialFilter==='scheme'&&m.kind.includes('схема'))||(ui.materialFilter==='document'&&!m.kind.includes('схема'))));return items.map(materialTile).join('')||empty('Ничего не найдено','Измените фильтр или запрос.','folder');}
function crmPage(){switch(ui.page){case 'today':return crmToday();case 'schedule':return crmSchedule();case 'requests':return crmRequests();case 'handoff':return crmHandoff();}return crmToday();}
function crmToday(){
  const active=state.crm.requests.filter(r=>r.stage!=='done'),newRequests=active.filter(r=>r.stage==='new');
  const awaiting=state.crm.appointments.filter(a=>a.date===DEMO_DATE&&a.status==='Не подтверждён');
  const handoffs=state.crm.handoffs.filter(h=>!h.done&&h.state==='received');
  return `${pageHeading('CRM / СЕГОДНЯ','Сегодня в клинике','Обращения, запись и выдача в одном рабочем дне.',button('Новое обращение','request-new','plus','primary'))}<div class="crm-stats"><button data-action="page" data-page="requests"><span class="stat-icon" data-tone="ice">${icon('chat')}</span><span><small>Новые обращения</small><strong>${newRequests.length}</strong></span>${icon('arrow',16)}</button><button data-action="page" data-page="schedule"><span class="stat-icon" data-tone="sand">${icon('calendar')}</span><span><small>Подтвердить запись</small><strong>${awaiting.length}</strong></span>${icon('arrow',16)}</button><button data-action="page" data-page="handoff"><span class="stat-icon" data-tone="petrol">${icon('box')}</span><span><small>Получено · следующий шаг</small><strong>${handoffs.length}</strong></span>${icon('arrow',16)}</button></div><div class="crm-command surface"><div><span class="eyebrow">СЕГОДНЯ В РАБОТЕ</span><h2>Входящие и ближайшие действия</h2></div><div class="command-view">${icon('sliders',16)}<span>По следующему действию</span></div></div><div class="crm-dashboard-grid"><section class="surface crm-inbox"><div class="surface-heading"><h2>${icon('chat')} Обращения</h2>${button('Доска','page','arrow','text-btn',`data-page="requests"`)}</div>${active.map(r=>requestRow(r)).join('')||empty('Всё разобрано','Новых действий по обращениям нет.','check-circle')}</section><section class="surface crm-next"><div class="surface-heading"><h2>${icon('box')} Выдача и контроль</h2>${button('Все','page','arrow','text-btn',`data-page="handoff"`)}</div>${state.crm.handoffs.filter(h=>!h.done).map(h=>handoffTile(h,true)).join('')}<div class="quiet-note">${icon('link',15)}<span>Основание выдачи — утверждённый план врача. Параметры линз остаются в Clinic и Orders.</span></div></section></div><section class="surface crm-day"><div class="surface-heading"><h2>${icon('calendar')} Записи на сегодня</h2>${button('Расписание','page','arrow','text-btn',`data-page="schedule"`)}</div><div class="crm-day-strip">${state.crm.appointments.filter(a=>a.date===DEMO_DATE&&a.status!=='Отменён').sort((a,b)=>a.time.localeCompare(b.time)).slice(0,5).map(a=>{const p=patientById(state,a.patientId);return `<button class="day-appointment" data-action="crm-patient" data-id="${p.id}"><time>${a.time}</time><b>${esc(p.name)}</b><small>${esc(a.kind)}</small>${badge(a.status,statusTone(a.status),true)}</button>`;}).join('')||empty('Нет записей','Добавьте запись на сегодня.','calendar')}</div></section>`;
}
function requestRow(r){return `<button class="request-row" data-action="request" data-id="${r.id}">${avatar(r,'small')}<span class="request-main"><b>${esc(r.name)}</b><small>${esc(r.subject)}</small><span class="request-channel">${esc(r.channel)} · ${esc(r.when)}</span></span><span class="request-next"><b>${esc(r.next)}</b><small>${esc(r.time)}</small></span>${icon('right',16)}</button>`;}
function handoffTile(h,compact=false){const p=patientById(state,h.patientId);return `<button class="handoff-tile ${h.done?'done':''} ${compact?'compact':''}" data-action="handoff" data-id="${h.id}"><div class="handoff-icon" data-tone="${h.approved?'petrol':'sand'}">${icon(h.state==='received'?'box':'calendar',20)}</div><div><span class="handoff-meta">${esc(h.order)} · ${esc(h.item)}</span><b>${esc(p.name)}</b><p>${esc(h.instruction)}</p><small>${h.done?'Выполнено':esc(h.due)} · ${h.approved?'План указан':'Нужно действие врача'}</small></div>${icon('arrow',15)}</button>`;}
function crmContext(){const isWeek=ui.page==='schedule'&&ui.scheduleView==='week',dates=ui.page==='schedule'?(isWeek?weekDates(ui.scheduleDate):[ui.scheduleDate]):[DEMO_DATE],budget=dates.length*600,total=periodAppointments(state.crm.appointments,dates).reduce((sum,a)=>sum+a.duration,0);return `<aside class="right-panel crm-context" aria-label="Контекст администратора" ${ui.side?'':'hidden'}><div class="context-heading"><span>${icon('sliders',16)} ${isWeek?'Контекст недели':'Контекст дня'}</span>${button('','toggle-side','close','icon-btn',`aria-label="Скрыть контекст"`)}</div><section class="context-section"><span class="section-label">АДМИНИСТРАТОР</span><div class="context-profile"><span class="avatar" data-tone="ice">АК</span><div><h3>Анна Ким</h3><p>Демо-профиль · на смене</p></div></div><div class="context-purpose"><span>${icon('shield',16)} Операционное пространство</span><p>Запись, обращения и следующий шаг. Клиническая карта остаётся в Clinic.</p></div></section><section class="context-section"><div class="context-section-title"><h3>${icon('calendar',16)} Время записей</h3></div><div class="capacity"><strong>${Math.round(total/budget*100)}<small>%</small></strong><span>${total} из ${budget} минут<br/>${isWeek?'в сетке Пн–Вс':fmtDate(dates[0])}</span></div><div class="capacity-bar"><span style="width:${Math.min(100,total/budget*100)}%"></span></div>${button('Открыть расписание','schedule','calendar','full')}</section><section class="context-section"><div class="context-section-title"><h3>${icon('bell',16)} Ближайшие действия</h3></div><div class="admin-next"><i data-tone="sand"></i><span><b>Подтвердить запись</b><small>Анна Ким · до 12:00</small></span>${button('','crm-patient','arrow','icon-btn',`data-id="dm-0194" aria-label="Открыть запись Анны Ким"`)}</div><div class="admin-next"><i data-tone="petrol"></i><span><b>Организовать примерку</b><small>Даниил Волков · 13:30</small></span>${button('','handoff','arrow','icon-btn',`data-id="h1" aria-label="Открыть задачу выдачи"`)}</div></section><section class="context-section"><div class="context-section-title"><h3>${icon('history',16)} Лента действий</h3></div>${state.crm.log.length?state.crm.log.slice(0,4).map(l=>`<div class="activity"><i></i><span><b>${esc(l.name)}</b><p>${esc(l.text)}</p><small>${esc(l.time)}</small></span></div>`).join(''):'<div class="activity"><i></i><span><b>Демо-день открыт</b><p>Действия в интерфейсе появятся здесь.</p><small>Сегодня · 09:00</small></span></div>'}</section><section class="context-section context-foot"><span class="section-label">СОХРАНЕНИЕ</span><p class="fine-print">CRM сохраняется отдельно от клинических черновиков.</p>${button('Сохранить CRM','save-crm','saved','full')}<span class="crm-save-state" data-save-state></span></section></aside>`;}
function crmSchedule(){
  const date=ui.scheduleDate,isWeek=ui.scheduleView==='week',dates=isWeek?weekDates(date):[date];
  const appointments=periodAppointments(state.crm.appointments,dates),minutes=appointments.reduce((sum,a)=>sum+a.duration,0);
  const hours=Array.from({length:10},(_,i)=>`${String(i+8).padStart(2,'0')}:00`);
  const switcher=`<div class="segmented schedule-views" aria-label="Масштаб расписания">${[['day','День'],['week','Неделя']].map(([value,label])=>button(label,'schedule-view','',ui.scheduleView===value?'active':'',`data-view="${value}" aria-pressed="${ui.scheduleView===value}"`)).join('')}</div>`;
  const toolbar=`<div class="schedule-toolbar">${switcher}<div class="date-selector">${button('','schedule-prev','left','icon-btn',`aria-label="${isWeek?'Предыдущая неделя':'Предыдущая дата расписания'}"`)}<label><span class="sr-only">Дата расписания</span><input type="date" data-schedule-date value="${date}"/></label>${button('','schedule-next','right','icon-btn',`aria-label="${isWeek?'Следующая неделя':'Следующая дата расписания'}"`)}</div>${button('Сегодня','schedule-today','','text-btn')}<div class="toolbar-spacer"></div><span class="schedule-doctor">${avatar({initials:'АМ',tone:'teal'},'small')} А. Мате</span></div>`;
  const overview=`<div class="schedule-period"><div><span class="eyebrow">${isWeek?'НЕДЕЛЯ · ПН–ВС':'ДЕНЬ'}</span><h2>${isWeek?weekLabel(date):fmtDate(date,true)}</h2></div><span class="schedule-totals">${badge(appointmentCount(appointments.length),'ice')}<span>${minutes} мин занято</span></span></div>`;
  const day=`<section class="surface schedule-calendar"><div class="calendar-head"><span>Время</span><div>${icon('eye',18)}<span><b>Кабинет 01 · А. Мате</b><small>Вымышленные записи · ${fmtDate(date,true)}</small></span></div></div><div class="calendar-body"><div class="hour-labels">${hours.map(h=>`<span>${h}</span>`).join('')}</div><div class="calendar-track">${hours.map((h,i)=>`<button class="calendar-slot" data-action="appointment" data-date="${date}" data-time="${h}" style="top:${i*84}px" aria-label="Добавить запись на ${h}"><span>${icon('plus',15)} Добавить запись</span></button>`).join('')}${appointments.map(a=>{const p=patientById(state,a.patientId),minutes=Number(a.time.slice(0,2))*60+Number(a.time.slice(3))-480;return `<button class="calendar-appointment" data-action="crm-patient" data-id="${p.id}" data-appointment="${a.id}" data-tone="${p.tone}" style="top:${minutes/60*84}px;height:${Math.max(43,a.duration/60*84)}px"><time>${a.time} — ${addMinutes(a.time,a.duration)}</time><b>${esc(p.name)}</b><span>${esc(a.kind)}</span>${badge(a.status,statusTone(a.status))}</button>`;}).join('')}</div></div></section>`;
  return `${pageHeading('CRM / РАСПИСАНИЕ','Расписание','Записи и свободное время · один врач в демо-пространстве',button('Записать пациента','appointment','plus','primary'))}${toolbar}${overview}${isWeek?weekCalendar(dates,appointments,hours):day}`;
}
function weekCalendar(dates,appointments,hours){
  const dayNames=['Пн','Вт','Ср','Чт','Пт','Сб','Вс'];
  return `<section class="surface week-calendar" aria-label="Расписание недели"><div class="week-caption"><span>${icon('eye',16)} Кабинет 01 · А. Мате</span><span>День — по заголовку · запись — по свободному слоту</span></div><div class="week-scroll" tabindex="0" role="region" aria-label="Недельный календарь. Прокрутите, чтобы увидеть другие дни и время."><div class="week-grid"><div class="week-head"><span class="week-axis-head">Время</span>${dates.map((date,i)=>{const items=appointments.filter(a=>a.date===date),minutes=items.reduce((sum,a)=>sum+a.duration,0);return `<button class="week-day-head ${date===ui.scheduleDate?'selected':''} ${date===DEMO_DATE?'today':''} ${i>4?'weekend':''}" data-action="schedule-day" data-date="${date}" ${date===DEMO_DATE?'aria-current="date"':''} aria-label="Открыть день: ${fmtDate(date,true)}; ${appointmentCount(items.length)}; ${minutes} минут занято"><span>${dayNames[i]} ${date===DEMO_DATE?'<i>Сегодня</i>':''}</span><b>${Number(date.slice(-2))}</b><small>${appointmentCount(items.length)} · ${minutes} мин</small><span class="week-load" aria-hidden="true"><i style="width:${Math.min(100,minutes/600*100)}%"></i></span></button>`;}).join('')}</div><div class="week-body"><div class="week-hours">${hours.map(h=>`<span>${h}</span>`).join('')}<span class="week-end-time">18:00</span></div>${dates.map((date,i)=>`<div class="week-track ${i>4?'weekend':''} ${date===ui.scheduleDate?'selected':''}" data-week-date="${date}">${Array.from({length:20},(_,n)=>{const time=addMinutes('08:00',n*30);return `<button class="week-slot" data-action="appointment" data-date="${date}" data-time="${time}" style="top:${n*48}px" aria-label="Добавить запись: ${fmtDate(date)} в ${time}"><span>${icon('plus',12)} ${time}</span></button>`;}).join('')}${appointments.filter(a=>a.date===date).map(a=>{const p=patientById(state,a.patientId),offset=Number(a.time.slice(0,2))*60+Number(a.time.slice(3))-480,parts=p.name.split(' '),shortName=`${parts.slice(1).join(' ')} ${parts[0][0]}.`,description=`${p.name} · ${fmtDate(date)} · ${a.time}–${addMinutes(a.time,a.duration)} · ${a.kind} · ${a.status}`;return `<button class="week-appointment ${a.duration>=45?'long':''}" data-action="crm-patient" data-id="${p.id}" data-appointment="${a.id}" data-tone="${p.tone}" style="top:${offset*1.6+2}px;height:${a.duration*1.6-4}px" aria-label="${esc(description)}" title="${esc(description)}"><time>${a.time} <i data-tone="${statusTone(a.status)}" aria-hidden="true"></i></time><b>${esc(shortName)}</b>${a.duration>=45?`<span>${esc(a.kind)}</span>`:''}</button>`;}).join('')}</div>`).join('')}</div></div></div><div class="week-foot">${icon('info',14)}<span>${appointments.length?'Показаны записи без отменённых. Свободное место — отсутствие записи в демо-календаре.':'На этой неделе нет записей. Выберите свободный слот, чтобы добавить первую.'} Часы сетки: 08:00–18:00.</span></div></section>`;
}

function crmRequests(){const filtered=state.crm.requests.filter(r=>ui.crmStage==='all'||r.stage===ui.crmStage),columns=[['new','Новые','ice'],['contact','В работе','sand'],['booked','Записаны','petrol'],['done','Завершены','sage']];return `${pageHeading('CRM / ОБРАЩЕНИЯ','Обращения','У каждого контакта есть ответственный и следующий шаг.',button('Новое обращение','request-new','plus','primary'))}<div class="board-toolbar"><div class="segmented">${[['all','Вся доска'],['new','Новые'],['contact','В работе']].map(([id,title])=>button(title,'crm-stage','',ui.crmStage===id?'active':'',`data-stage="${id}" aria-pressed="${ui.crmStage===id}"`)).join('')}</div><span class="muted">${filtered.length} обращений · демо</span></div><div class="request-board">${columns.map(([id,title,tone])=>`<section class="board-column" data-tone="${tone}"><div class="board-column-head"><h2><i></i>${title}</h2><span>${filtered.filter(r=>r.stage===id).length}</span></div><div class="board-column-list">${filtered.filter(r=>r.stage===id).map(r=>`<button class="request-card" data-action="request" data-id="${r.id}"><div class="request-card-person">${avatar(r,'small')}<span><b>${esc(r.name)}</b><small>${esc(r.channel)}</small></span></div><h3>${esc(r.subject)}</h3><p>${esc(r.note)}</p><div class="request-card-next">${icon('arrow',14)} ${esc(r.next)}</div><div class="request-card-foot"><span>${icon('clock',13)} ${esc(r.time)}</span><span class="owner-avatar" title="Ответственный: ${esc(r.owner)}">${esc(initialsText(r.owner))}</span></div></button>`).join('')||'<div class="board-empty">Нет обращений на этом этапе</div>'}</div>${id==='new'?button('Добавить обращение','request-new','plus','board-add'):''}</section>`).join('')}</div><div class="board-foot">${icon('info',16)} Этап меняется в карточке обращения. Сообщения и звонки из прототипа не отправляются.</div>`;}
function crmHandoff(){return `${pageHeading('CRM / ВЫДАЧА И КОНТРОЛЬ','Выдача и контроль','Физическое получение, утверждённый план и запись пациента.')}<div class="handoff-steps"><span>${icon('box')} Получено</span>${icon('arrow',16)}<span>${icon('document')} План врача</span>${icon('arrow',16)}<span>${icon('calendar')} Запись / выдача</span>${icon('arrow',16)}<span>${icon('check-circle')} Контроль</span></div><section class="surface handoff-table"><div class="surface-heading"><h2>В работе</h2>${badge(`${state.crm.handoffs.filter(h=>!h.done).length} задачи`,'petrol')}</div>${state.crm.handoffs.map(h=>handoffTile(h)).join('')}</section><div class="handoff-boundary surface"><span class="subject-icon" data-tone="ice">${icon('shield',24)}</span><div><h3>Администратору — понятное действие</h3><p>CRM показывает операционную задачу и наличие плана. Клинические параметры, основания подбора и заключение доступны в отдельном контуре Clinic.</p></div></div>`;}
function focusToken(){
  const el=document.activeElement;if(!el||!root.contains(el)||el===root)return null;
  const attributes=[...el.attributes].filter(a=>a.name.startsWith('data-')||a.name==='id').map(a=>[a.name,a.value]);
  const zone=el.closest('.clinical-tabs,.view-tabs,.expanded-actions,.record-toolbar,.module-switch,.registry-toolbar');
  return {tag:el.tagName.toLowerCase(),attributes,zone:zone?'.'+zone.classList[0]:null};
}
function restoreFocus(token){
  if(!token)return;const scope=token.zone?root.querySelector(token.zone):root;
  const target=scope&&[...scope.querySelectorAll(token.tag)].find(el=>token.attributes.every(([k,v])=>el.getAttribute(k)===v));
  if(target)target.focus({preventScroll:true});
  else if(token.zone==='.expanded-actions')document.querySelector('.clinical-tabs [aria-selected="true"]')?.focus({preventScroll:true});
}
function render(){
  const previousFocus=focusToken();
  document.title=`Dr. Mate · ${ui.module==='clinic'?'Clinic':'CRM'}`;
  const patientLayout=ui.module==='clinic'&&ui.page==='patient';
  root.innerHTML=`${header()}<div class="workspace ${ui.side?'':'without-context'} ${ui.wide&&patientLayout?'wide':''} ${ui.contextDrawer?'context-open':''}" data-module="${ui.module}">${queue()}<main id="main" tabindex="-1" class="main ${patientLayout?'patient-main':''}">${ui.module==='crm'?crmPage():ui.page==='today'?todayPage():ui.page==='patient'?patientPage():ui.page==='patients'?patientsPage():materialsPage()}<footer class="workspace-footer"><span>Dr. Mate · ${ui.module==='clinic'?'Clinic':'CRM'} <i>/</i> Новое представление</span><span>08.10.2026 · Демо-концепция</span></footer></main>${rightPanel()}</div><input id="file-picker" type="file" accept="image/png,image/jpeg,image/webp,image/gif,application/pdf,text/plain" hidden/>`;
  const weekScroll=root.querySelector('.week-scroll'),selectedDay=root.querySelector('.week-day-head.selected');
  if(weekScroll&&selectedDay)weekScroll.scrollLeft=Math.max(0,selectedDay.offsetLeft-46);
  restoreFocus(previousFocus);updateSaveIndicator();if(storageWarning){notice(storageWarning);storageWarning='';}
}
function showDialog(title,body,className=''){
  if(!dialog.open)dialogFocus=document.activeElement;dialog.className=className;
  dialog.innerHTML=`<div class="dialog-head"><div><span class="eyebrow">DR. MATE · ДЕМО-ПРОСТРАНСТВО</span><h2 id="dialog-title">${esc(title)}</h2></div>${button('','close-dialog','close','icon-btn',`aria-label="Закрыть окно"`)}</div><div class="dialog-body">${body}</div>`;
  if(!dialog.open)dialog.showModal();(dialog.querySelector('input:not([type=hidden]),select,textarea')??dialog.querySelector('[data-action="close-dialog"]'))?.focus();
}
function closeDialog(){dialog.close();}
dialog.addEventListener('close',()=>{if(dialogFocus?.isConnected)dialogFocus.focus({preventScroll:true});else document.querySelector('#main')?.focus({preventScroll:true});});
function openSearch(){showDialog('Найти в пространстве',`<label class="dialog-search">${icon('search')}<input type="search" id="workspace-search" placeholder="Имя, запись, жалоба, материал…" aria-label="Глобальный поиск" autocomplete="off"/></label><div id="search-results"><div class="search-start">${icon('search',32)}<p>Ищите пациента или запись по содержимому.<br/>Например, «Соколова», «комфорт» или «топография».</p></div></div>`,'search-dialog');dialog.querySelector('input').focus();}
function renderSearch(query){const target=dialog.querySelector('#search-results');if(!target)return;const results=searchWorkspace(state,query),q=query.toLocaleLowerCase('ru').trim(),materials=MATERIALS.filter(m=>q&&`${m.title} ${m.kind}`.toLocaleLowerCase('ru').includes(q));target.innerHTML=results.map(r=>`<button class="search-result" data-action="search-result" data-id="${r.patientId}" data-record="${r.recordId??''}"><span class="result-icon">${icon(r.kind==='patient'?'people':'document')}</span><span><b>${esc(r.title)}</b><small>${esc(r.subtitle)}</small></span>${icon('arrow',16)}</button>`).join('')+materials.map(m=>`<button class="search-result" data-action="material" data-id="${m.id}"><span class="result-icon">${icon('folder')}</span><span><b>${esc(m.title)}</b><small>${esc(m.kind)}</small></span>${icon('arrow',16)}</button>`).join('')||empty(q?'Ничего не найдено':'Введите запрос',q?'Попробуйте имя, название или слово из записи.':'Поиск работает по вымышленным записям.');}
function appointmentDialog(time='',date=''){
  showDialog('Записать пациента',`<form id="appointment-form"><div class="form-grid two"><label class="field span-two"><span>Пациент</span><select name="patientId" required><option value="">Выберите демо-пациента</option>${state.patients.map(p=>`<option value="${p.id}" ${ui.patientId===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label class="field"><span>Дата</span><input type="date" name="date" required value="${date||(ui.module==='crm'?ui.scheduleDate:ui.queueDate??DEMO_DATE)}"/></label><label class="field"><span>Время</span><input type="time" name="time" required value="${esc(time||'12:30')}" min="08:00" max="17:30"/></label><label class="field"><span>Длительность</span><select name="duration"><option value="30">30 минут</option><option value="45">45 минут</option><option value="60">60 минут</option></select></label><label class="field"><span>Тип записи</span><select name="kind"><option>Контрольный осмотр</option><option>Первичная консультация</option><option>Примерка и выдача</option><option>Консультация</option></select></label></div><p class="form-error" role="alert" hidden></p><div class="dialog-actions">${button('Отмена','close-dialog')}<button type="submit" class="btn primary">${icon('check')} Добавить демо-запись</button></div></form>`);
}
function requestDialog(id){const r=state.crm.requests.find(x=>x.id===id);if(!r)return;showDialog(r.name,`<div class="request-detail-meta">${badge(r.channel,'ice')}<span>${esc(r.when)}</span></div><h3>${esc(r.subject)}</h3><p class="detail-note">${esc(r.note)}</p><form id="request-form" data-id="${r.id}"><div class="form-grid two"><label class="field"><span>Этап обращения</span><select name="stage">${[['new','Новое'],['contact','В работе'],['booked','Записан'],['done','Завершено']].map(([v,t])=>`<option value="${v}" ${r.stage===v?'selected':''}>${t}</option>`).join('')}</select></label><label class="field"><span>Ответственный</span><input name="owner" value="${esc(r.owner)}" required/></label><label class="field span-two"><span>Следующее действие</span><input name="next" value="${esc(r.next)}" required/></label><label class="field span-two"><span>Операционная заметка</span><textarea name="note" rows="3">${esc(r.note)}</textarea></label></div><div class="form-note">${icon('info',15)}<span>Изменения остаются в демо-CRM. Звонки и сообщения не отправляются.</span></div><div class="dialog-actions">${button('К доске обращений','requests-back','left','text-btn')}${r.patientId?button('Посмотреть запись','crm-patient','calendar','',`data-id="${r.patientId}" data-appointment="${esc(r.appointmentId??'')}"`):button('Применить и записать','request-schedule','calendar','',`data-id="${r.id}"`)}<button class="btn primary" type="submit">${icon('check')} Применить</button></div></form>`);}
