function crmPatientDialog(id,appointmentId=null){const p=crmProjection(state,id);if(!p)return;const a=p.appointments.find(x=>x.id===appointmentId)??p.appointments.find(x=>x.date===DEMO_DATE)??p.appointments[0];showDialog(p.name,`<div class="admin-profile">${avatar(p,'large')}<div>${badge(p.id.toUpperCase(),'ice')}<p>Контакт: ${p.contact}</p></div></div>${a?`<div class="detail-grid"><div><span>Дата и время</span><b>${fmtDate(a.date)} · ${a.time}</b></div><div><span>Тип записи</span><b>${esc(a.kind)}</b></div><div><span>Врач</span><b>А. Мате · кабинет 01</b></div><div><span>Длительность</span><b>${a.duration} минут</b></div></div><form id="appointment-status-form" data-id="${a.id}"><label class="field"><span>Статус записи</span><select name="status">${['Не подтверждён','Подтверждён','Ожидает','В кабинете','Приём завершён','Отменён'].map(s=>`<option ${s===a.status?'selected':''}>${s}</option>`).join('')}</select></label><div class="dialog-actions">${button('Отмена','close-dialog')}<button class="btn primary" type="submit">Применить</button></div></form>`:'<p>У пациента пока нет демо-записей.</p>'}<div class="admin-boundary">${icon('shield',17)}<p>Это операционная карточка. Измерения, исследования и заключение сюда не передаются.</p></div>`);}
function handoffDialog(id){const h=state.crm.handoffs.find(x=>x.id===id);if(!h)return;const p=patientById(state,h.patientId);showDialog(`${p.name} · следующий шаг`,`<div class="request-detail-meta">${badge(h.order,'petrol')}${badge(h.state==='received'?'Получено физически':'Контроль после выдачи','ice')}</div><div class="handoff-plan" data-tone="${h.approved?'petrol':'sand'}"><span>${icon(h.approved?'check-circle':'clock',22)}</span><div><h3>${esc(h.instruction)}</h3><p>${esc(h.source)}</p></div></div><div class="detail-grid"><div><span>Позиция</span><b>${esc(h.item)}</b></div><div><span>Следующее действие</span><b>${esc(h.due)}</b></div></div>${!h.approved?'<div class="form-note">'+icon('info',16)+'<span>План врача не указан. Прототип не предлагает режим ношения или клинический срок.</span></div>':''}<div class="dialog-actions">${button('Записать пациента','handoff-schedule','calendar','',`data-id="${p.id}"`)}${button(h.done?'Вернуть в работу':'Отметить выполненным','handoff-done','check','primary',`data-id="${h.id}" ${h.approved?'':'disabled'}`)}</div>`);}
function materialDialog(id){const m=MATERIALS.find(m=>m.id===id);if(!m)return;const p=patientById(state,m.patientId);let content='';if(id==='topography')content=`<div class="material-viewer topo-viewer"><div class="topo-eye"><span>OD</span>${topo('view-od')}</div><div class="topo-eye"><span>OS</span>${topo('view-os')}</div></div><div class="scheme-caption">Учебная схема · цвета и геометрия иллюстративны, числовые результаты не выводятся.</div>`;else if(id==='oct')content=`<div class="material-viewer oct-viewer">${oct()}</div><div class="scheme-caption">Учебная схема ОКТ · не изображение пациента и не диагностическая модель.</div>`;else if(id==='plan')content=`<article class="document-preview"><span class="eyebrow">ЗАМЫСЕЛ ВРАЧА · УЧЕБНАЯ ВЕРСИЯ 2</span><h3>Задача этой пары</h3><h4>Что проверяем</h4><p>Комфорт к концу дня и записанное качество зрения на контрольном визите.</p><h4>Что хотели сохранить</h4><p>Записанную коррекцию и понятную связь с исходным исследованием.</p><h4>Основание оценки</h4><p>Ответ пациента, новые наблюдения врача и сопоставление с предыдущей записью. Ожидания оцениваются отдельно; отсутствующие данные не заменяются предположением.</p><div class="form-note">${icon('info',16)} Это иллюстрация интерфейса замысла, а не клиническая рекомендация.</div></article>`;else content=`<article class="document-preview"><span class="eyebrow">ДЕМО-ДОКУМЕНТ</span><h3>Подготовка к визиту</h3><p>Составить список вопросов врачу. Взять сведения о используемой коррекции и прежние заключения, если они есть.</p><p>Индивидуальные указания по режиму ношения или перерыву определяет врач. Универсального срока в этом документе нет.</p></article>`;showDialog(m.title,`<div class="material-meta">${badge(m.kind,m.tone)}<span>${m.date}${p?` · ${esc(p.name)}`:''}</span></div>${content}<div class="dialog-actions">${p?button('Открыть карту','material-patient','arrow','',`data-id="${p.id}"`):''}${button('Закрыть','close-dialog')}</div>`,'material-dialog');}
function aboutDialog(){showDialog('Новое пространство Dr. Mate',`<div class="about-lead">${orbit('about',true)}<div><h3>Clinic · новое представление.<br/>CRM · новая перспектива.</h3><p>Самостоятельный интерфейс от 8 октября 2026 года. Все пациенты, записи и задачи вымышленные.</p></div></div><div class="about-grid"><div><h4>Что можно пройти</h4><p>Рабочий день → карта → разделы приёма → сравнение визитов → итог. В CRM — обращения, расписание, выдача и контроль.</p></div><div><h4>Как сохраняется работа</h4><p>В пределах вкладки поля сохраняются при навигации. «Сохранить» создаёт локальную демо-копию в этом браузере. Clinic и CRM сохраняются отдельно.</p></div><div><h4>Что остаётся концепцией</h4><p>Живые интеграции, авторизация, серверное хранение, клинические протоколы, подпись и реальные сообщения.</p></div><div><h4>Визуальная основа</h4><p>Текущий Flux: три рабочие области, компактная очередь, тонкие контуры и прохладные поверхности. Весь интерфейс Clinic создан заново.</p></div></div><div class="dialog-actions">${button('Начать с рабочего дня','tour-start','play','primary')}${button('Продолжить просмотр','close-dialog')}</div>`,'about-dialog');}
