function selectRecord(id){if(!recordById(state,ui.patientId,id))return;ui.recordId=id;ui.section='overview';if(ui.compareId===id)ui.compareId=null;render();}
function pinSection(id){if(!SECTIONS.some(s=>s.id===id))return;const p=currentPatient(),r=currentRecord();state.pins[p.id]??=[];const pins=state.pins[p.id],index=pins.findIndex(x=>x.section===id&&x.recordId===r.id);if(index>=0)pins.splice(index,1);else pins.push({section:id,recordId:r.id});setDirty(p.id);ui.side=true;if(window.innerWidth<=1000)ui.contextDrawer=true;render();notice(index>=0?'Карточка откреплена.':'Карточка закреплена с датой и источником.');}
function completeDialog(){const r=currentRecord();if(!r)return;if(!r.decision.trim()){ui.section='conclusion';render();document.querySelector('[data-field="decision"]')?.focus();notice('Добавьте решение врача, чтобы завершить учебный приём.');return;}showDialog('Завершить учебный приём?',`<p>Запись станет исторической и будет доступна только для чтения. Решение врача и введённые значения сохранятся в локальной демо-копии.</p><div class="completion-review"><span class="section-label">РЕШЕНИЕ ВРАЧА</span><p>${esc(r.decision)}</p><span class="section-label">СЛЕДУЮЩИЙ ШАГ</span><p>${esc(r.plan||'Не указан')}</p></div><p class="fine-print">Это состояние прототипа, без электронной подписи и серверного clinical runtime.</p><div class="dialog-actions">${button('Продолжить редактирование','close-dialog')}${button('Завершить и сохранить','complete-confirm','check','primary')}</div>`);}
function newVisitDialog(){showDialog('Начать приём',`<p>Выберите демо-пациента. Для открытого черновика работа продолжится; новый визит после завершённой записи начнётся с пустых наблюдений.</p><div class="visit-patients">${state.patients.map(p=>`<button data-action="visit-patient" data-id="${p.id}">${avatar(p,'small')}<span><b>${esc(p.name)}</b><small>${ageText(p.age)} · ${p.id.toUpperCase()}</small></span>${icon('arrow',16)}</button>`).join('')}</div>`);}
function taskDialog(){showDialog('Задача врача',`<form id="task-form"><label class="field"><span>Следующее действие</span><input name="text" required maxlength="250" placeholder="Что нужно сделать?"/></label><div class="form-grid two"><label class="field"><span>Пациент</span><select name="patientId">${state.patients.map(p=>`<option value="${p.id}" ${p.id===ui.patientId?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label class="field"><span>Срок</span><input name="time" value="Сегодня" required maxlength="60"/></label></div><div class="dialog-actions">${button('Отмена','close-dialog')}<button type="submit" class="btn primary">Добавить задачу</button></div></form>`);}
function knowledgeDialog(){showDialog('Knowledge · источник знаний',`<div class="integration-intro">${icon('book',32)}<div><h3>Справочник рядом с клинической работой</h3><p>Каталоги, источники и версии правил остаются отдельным модулем. Карта пациента не передаётся в Knowledge.</p></div></div><div class="knowledge-topics"><div>${icon('lens',23)}<span><b>Каталоги контактных линз</b><small>Проверяемые сведения производителя</small></span>${badge('Концепция','ice')}</div><div>${icon('document',23)}<span><b>Источники и версии</b><small>Происхождение каждого факта</small></span>${badge('Концепция','ice')}</div><div>${icon('focus',23)}<span><b>Объяснимые протоколы</b><small>Без автоматического назначения</small></span>${badge('Концепция','ice')}</div></div><div class="form-note">${icon('info',16)} В этом прототипе показано место модуля в рабочем пространстве. Живая интеграция не подключена.</div>`);}
function ordersDialog(){const p=currentPatient();showDialog('Flux · Orders',`<div class="integration-intro">${icon('box',32)}<div><h3>Заказ сохраняет своё основание</h3><p>Исследование, запрошенные параметры и лабораторное подтверждение остаются различными сущностями.</p></div></div><div class="lineage-demo"><div><span>Clinic · исследование</span><b>${p?.id==='dm-0148'?'12.05.2026 · первичный подбор':'Исходный визит'}</b><small>Исходная запись и её версия</small></div>${icon('arrow',18)}<div><span>Orders · основание</span><b>Явная ссылка</b><small>Не «последняя рефракция»</small></div>${icon('arrow',18)}<div><span>CRM · действие</span><b>Запись или выдача</b><small>Минимальный операционный контекст</small></div></div><p class="fine-print">Схема иллюстрирует принятый принцип. Отправка заказа, shared identity и договор API здесь не реализованы.</p>`,'wide-dialog');}
function fileIssue(file){if(file.size>20*1024*1024)return 'Для просмотра выберите файл до 20 МБ.';if(!['image/png','image/jpeg','image/webp','image/gif','application/pdf','text/plain'].includes(file.type)&&!file.name.toLowerCase().endsWith('.txt'))return 'Предпросмотр доступен для PNG, JPEG, WebP, GIF, PDF и TXT.';return ''; }
async function fileDialog(file,slot=null){
  const issue=fileIssue(file);if(issue){notice(issue);return;}
  let content,url;
  if(file.type==='text/plain'||file.name.endsWith('.txt'))content=`<pre class="local-text">${esc(await file.text())}</pre>`;
  else{url=URL.createObjectURL(file);content=file.type==='application/pdf'?`<iframe class="local-pdf" title="${esc(file.name)}" src="${url}"></iframe>`:`<img class="local-image" src="${url}" alt="${esc(file.name)}"/>`;}
  showDialog(file.name,`${content}<div class="file-info">${icon('shield',15)}<span>Локальный файл · ${(file.size/1024).toFixed(0)} КБ · доступен только в этой вкладке</span></div><div class="dialog-actions">${slot!==null?button('Освободить слот','file-remove','close','',`data-slot="${slot}"`):''}${button('Закрыть','close-dialog')}</div>`,'material-dialog');
  if(url)dialog.addEventListener('close',()=>URL.revokeObjectURL(url),{once:true});
}
let pendingSlot=null;
function chooseFile(slot=null){pendingSlot=slot;const picker=document.querySelector('#file-picker');picker.value='';picker.click();}
async function handleAction(action,el){
  switch(action){
    case 'home':navigate({module:'clinic',page:'today'});break;
    case 'module':if(dialog.open)closeDialog();navigate({module:el.dataset.module,page:'today',wide:false});break;
    case 'page':navigate({page:el.dataset.page,wide:false});break;
    case 'patient':openPatient(el.dataset.id);break;
    case 'section':ui.section=el.dataset.section;render();document.querySelector('#main')?.scrollTo(0,0);break;
    case 'next-section':{const index=SECTIONS.findIndex(s=>s.id===ui.section);ui.section=SECTIONS[index+1]?.id??'overview';render();document.querySelector('.clinical-tabs [aria-selected="true"]')?.focus();document.querySelector('#main')?.scrollTo(0,0);break;}
    case 'search':openSearch();break;
    case 'search-result':closeDialog();openPatient(el.dataset.id,el.dataset.record||null);break;
    case 'theme':{const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;try{localStorage.setItem(`${STORAGE_PREFIX}.theme`,theme);}catch{}render();break;}
    case 'toggle-side':if(window.innerWidth<=1000){ui.contextDrawer=!ui.contextDrawer;ui.side=true;ui.mobileQueue=false;}else ui.side=!ui.side;render();if(ui.contextDrawer)document.querySelector('.right-panel')?.focus({preventScroll:true});break;
    case 'mobile-queue':ui.mobileQueue=!ui.mobileQueue;ui.contextDrawer=false;render();if(ui.mobileQueue)document.querySelector('.left-panel')?.focus({preventScroll:true});break;
    case 'wide':ui.wide=!ui.wide;render();break;
    case 'queue-filter':ui.queueFilter=el.dataset.filter;render();break;
    case 'registry-filter':ui.registryFilter=el.dataset.filter;render();break;
    case 'material-filter':ui.materialFilter=el.dataset.filter;render();break;
    case 'crm-stage':ui.crmStage=el.dataset.stage;render();break;
    case 'materials':navigate({module:'clinic',page:'materials'});break;
    case 'material':materialDialog(el.dataset.id);break;
    case 'material-patient':closeDialog();openPatient(el.dataset.id);break;
    case 'knowledge':knowledgeDialog();break;
    case 'orders':ordersDialog();break;
    case 'save':if(ui.patientId&&saveDomain(ui.patientId))notice('Учебная карта сохранена на этом устройстве.');break;
    case 'save-crm':if(saveDomain('crm'))notice('CRM сохранена отдельно от клинических черновиков.');break;
    case 'force-save':{const domain=el.dataset.domain;closeDialog();if(saveDomain(domain,true))notice('Локальная копия заменена текущей работой.');break;}
    case 'complete':completeDialog();break;
    case 'complete-confirm':{const r=currentRecord();completeEncounter(state,ui.patientId,r.id);setDirty(ui.patientId);closeDialog();const ok=saveDomain(ui.patientId);render();if(ok)notice('Учебный приём завершён и сохранён на устройстве.');break;}
    case 'new-visit':newVisitDialog();break;
    case 'visit-patient':{const id=el.dataset.id;const r=newEncounter(state,id);closeDialog();openPatient(id,r.id);break;}
    case 'patient-new':{const r=newEncounter(state,ui.patientId);setDirty(ui.patientId);ui.recordId=r.id;ui.section='interview';ui.compareId=null;render();notice('Новый приём начат. Наблюдения и решение пустые.');break;}
    case 'import':{const result=importDemo(state,ui.patientId,ui.recordId);setDirty(ui.patientId);render();notice(`Учебный пакет: ${result.filled} полей заполнено, ${result.kept} ручных значений сохранено.`);break;}
    case 'history':historyDialog();break;
    case 'history-open':closeDialog();selectRecord(el.dataset.record);break;
    case 'record-open':selectRecord(el.dataset.record);break;
    case 'history-compare':closeDialog();ui.compareId=el.dataset.record;render();break;
    case 'compare':{if(ui.compareId){ui.compareId=null;render();break;}const others=state.records[ui.patientId].filter(r=>r.id!==ui.recordId);if(!others.length){notice('Для сравнения нужен ещё один визит.');break;}ui.compareId=others[0].id;render();break;}
    case 'compare-close':ui.compareId=null;render();document.querySelector('[data-action="compare"]')?.focus({preventScroll:true});break;
    case 'compare-focus':document.querySelector('.comparison-panel')?.focus();document.querySelector('.comparison-panel')?.scrollIntoView({block:'start',behavior:'smooth'});break;
    case 'current-focus':document.querySelector('.clinical-tabs [aria-selected="true"]')?.focus();document.querySelector('#main')?.scrollTo(0,0);window.scrollTo?.(0,0);break;
    case 'pin':pinSection(el.dataset.section);break;
    case 'unpin':{state.pins[ui.patientId]=(state.pins[ui.patientId]??[]).filter(pin=>`${pin.recordId}:${pin.section}`!==el.dataset.key);setDirty(ui.patientId);render();break;}
    case 'pin-open':ui.recordId=el.dataset.record;ui.section=el.dataset.section;if(ui.compareId===ui.recordId)ui.compareId=null;render();break;
    case 'appointment':appointmentDialog(el.dataset.time||'',el.dataset.date||'');break;
    case 'schedule':navigate({module:'crm',page:'schedule',wide:false,scheduleDate:DEMO_DATE});break;
    case 'day-prev':case 'day-next':ui.queueDate=shiftDate(ui.queueDate??DEMO_DATE,action==='day-prev'?-1:1);render();break;
    case 'schedule-view':ui.scheduleView=el.dataset.view==='week'?'week':'day';render();break;
    case 'schedule-day':navigate({scheduleDate:el.dataset.date,scheduleView:'day'});break;
    case 'schedule-prev':case 'schedule-next':ui.scheduleDate=shiftDate(ui.scheduleDate,(action==='schedule-prev'?-1:1)*(ui.scheduleView==='week'?7:1));render();break;
    case 'schedule-today':ui.scheduleDate=DEMO_DATE;render();break;
    case 'request':requestDialog(el.dataset.id);break;
    case 'request-new':newRequestDialog();break;
    case 'request-schedule':{const formBefore=dialog.querySelector('#request-form');if(!formBefore.checkValidity()){formBefore.reportValidity();break;}const values=Object.fromEntries(new FormData(formBefore));const r=applyRequest(formBefore.dataset.id,values);appointmentDialog();const form=dialog.querySelector('form');form.dataset.requestId=r.id;form.insertAdjacentHTML('afterbegin',`<div class="form-note">${icon('link',16)}<span>Обращение: ${esc(r.name)}. Явно выберите соответствующего демо-пациента; новый пациент здесь автоматически не создаётся.</span></div>`);form.querySelector('[name="patientId"]').value=r.patientId||'';form.querySelector('[data-action="close-dialog"]').outerHTML=button('Вернуться к обращению','request','left','',`data-id="${r.id}"`);break;}
    case 'requests-back':closeDialog();navigate({module:'crm',page:'requests'});break;
    case 'crm-patient':crmPatientDialog(el.dataset.id,el.dataset.appointment);break;
    case 'handoff':handoffDialog(el.dataset.id);break;
    case 'handoff-schedule':closeDialog();appointmentDialog();dialog.querySelector('[name="patientId"]').value=el.dataset.id;break;
    case 'handoff-done':{const h=markHandoff(state,el.dataset.id);state.crm.log.unshift({id:`event-${Date.now()}`,name:patientById(state,h.patientId).name,text:h.done?'Операционный шаг отмечен выполненным':'Операционный шаг возвращён в работу',time:'Сейчас'});setDirty('crm');closeDialog();render();notice(h.done?'Операционный шаг выполнен в демо.':'Задача возвращена в работу.');break;}
    case 'new-task':taskDialog();break;
    case 'show-tasks':showDialog('Задачи рабочего дня',`<div class="tasks">${state.tasks.map(t=>`<label class="task ${t.done?'done':''}"><input type="checkbox" data-task="${t.id}" ${t.done?'checked':''}/><span>${esc(t.text)}<small>${esc(patientById(state,t.patientId)?.name??'')} · ${esc(t.time)}</small></span></label>`).join('')}</div><div class="dialog-actions">${button('Новая задача','new-task','plus')}${button('Закрыть','close-dialog')}</div>`);break;
    case 'unfinished':showDialog('Незавершённые записи',`<div class="visit-patients">${Object.values(state.records).flat().filter(r=>r.status==='draft'&&(r.complaint||r.findings)).map(r=>{const p=patientById(state,r.patientId);return `<button data-action="history-patient" data-id="${p.id}" data-record="${r.id}">${avatar(p,'small')}<span><b>${esc(p.name)}</b><small>${fmtDate(r.date)} · ${esc(r.title)}</small></span>${icon('arrow',16)}</button>`;}).join('')||empty('Все записи завершены','Открытых заполненных черновиков нет.','check-circle')}</div>`);break;
    case 'history-patient':closeDialog();openPatient(el.dataset.id,el.dataset.record);break;
    case 'file':{const slot=Number(el.dataset.slot),f=files.get(slot);if(f)await fileDialog(f,slot);else chooseFile(slot);break;}
    case 'file-remove':files.delete(Number(el.dataset.slot));closeDialog();render();break;
    case 'attach-material':chooseFile();break;
    case 'about':aboutDialog();break;
    case 'profile':showDialog('Рабочий профиль',`<div class="admin-profile">${avatar({initials:'АМ',tone:'teal'},'large')}<div><h3>А. Мате</h3><p>Демонстрационный профиль врача</p></div></div><p>Переключение Clinic и CRM позволяет оценить два отдельных пространства. Это не реализация ролей или разграничения доступа.</p><div class="dialog-actions">${button('О прототипе','about','info')}${button('Закрыть','close-dialog')}</div>`);break;
    case 'tour-start':closeDialog();navigate({module:'clinic',page:'today'});break;
    case 'close-dialog':closeDialog();break;
  }
}
function clickable(e){const el=e.target.closest('[data-action]');if(!el||el.disabled)return;e.preventDefault();Promise.resolve(handleAction(el.dataset.action,el)).catch(error=>notice(error.message));}
root.addEventListener('keydown',e=>{const tab=e.target.closest('.clinical-tabs [role="tab"]');if(!tab||!['ArrowRight','ArrowLeft','Home','End'].includes(e.key))return;e.preventDefault();const ids=['overview',...SECTIONS.map(s=>s.id)],index=ids.indexOf(tab.dataset.section);ui.section=e.key==='Home'?ids[0]:e.key==='End'?ids.at(-1):ids[(index+(e.key==='ArrowRight'?1:-1)+ids.length)%ids.length];render();document.querySelector('.clinical-tabs [aria-selected="true"]')?.focus();});
root.addEventListener('click',clickable);dialog.addEventListener('click',clickable);
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});
toast.addEventListener('click',e=>{if(e.target.closest('[data-toast-close]'))toast.hidden=true;});
function inputHandler(e){const el=e.target;
  if(el.matches('[data-field]')){try{updateField(state,ui.patientId,ui.recordId,el.dataset.field,el.value);setDirty(ui.patientId);}catch(error){notice(error.message);}return;}
  if(el.matches('[data-queue-search]')){ui.patientQuery=el.value;const q=ui.patientQuery.toLocaleLowerCase('ru');const date=ui.queueDate??DEMO_DATE;const items=state.crm.appointments.filter(a=>a.date===date&&a.status!=='Отменён'&&(ui.queueFilter==='all'||(ui.queueFilter==='waiting'&&['Ожидает','В кабинете'].includes(a.status))||(ui.queueFilter==='upcoming'&&a.time>='11:00'))&&`${patientById(state,a.patientId).name} ${a.patientId}`.toLocaleLowerCase('ru').includes(q)).sort((a,b)=>a.time.localeCompare(b.time));document.querySelector('[data-queue-list]').innerHTML=queueItems(items);}
  if(el.matches('[data-registry-search]')){ui.registryQuery=el.value;document.querySelector('[data-registry-list]').innerHTML=registryItems();}
  if(el.matches('[data-material-search]')){ui.materialQuery=el.value;document.querySelector('[data-material-list]').innerHTML=materialItems();}
  if(el.id==='workspace-search')renderSearch(el.value);
}
root.addEventListener('input',inputHandler);dialog.addEventListener('input',inputHandler);
function changeHandler(e){const el=e.target;
  if(el.matches('[data-record-select]'))selectRecord(el.value);
  if(el.matches('[data-comparison-select]')){ui.compareId=el.value;render();}
  if(el.matches('[data-expectation]')){updateField(state,ui.patientId,ui.recordId,`expectations.${el.dataset.expectation}`,el.value);setDirty(ui.patientId);}
  if(el.matches('[data-task]')){const t=state.tasks.find(t=>t.id===el.dataset.task);if(t){t.done=el.checked;setDirty(t.patientId);el.closest('.task').classList.toggle('done',t.done);}}
  if(el.matches('[data-schedule-date]')){if(el.value){ui.scheduleDate=el.value;render();}}
  if(el.id==='file-picker'){const f=el.files?.[0];if(f){const issue=fileIssue(f);if(issue){notice(issue);pendingSlot=null;return;}if(pendingSlot!==null){files.set(pendingSlot,f);render();notice('Файл закреплён в этой вкладке.');}else fileDialog(f);}pendingSlot=null;}
}
root.addEventListener('change',changeHandler);dialog.addEventListener('change',changeHandler);
function applyRequest(id,values){const r=moveRequest(state,id,values.stage);Object.assign(r,{owner:values.owner.trim(),next:values.next.trim(),note:values.note});setDirty('crm');return r;}
dialog.addEventListener('submit',e=>{
  e.preventDefault();const form=e.target;const values=Object.fromEntries(new FormData(form));
  try{
    if(form.id==='appointment-form'){const a=scheduleAppointment(state,values);const request=state.crm.requests.find(r=>r.id===form.dataset.requestId);if(request){request.patientId=a.patientId;request.appointmentId=a.id;request.stage='booked';request.next='Подтвердить запись';request.time=`${fmtDate(a.date)} · ${a.time}`;}state.crm.log.unshift({id:`event-${Date.now()}`,name:patientById(state,a.patientId).name,text:`Добавлена запись на ${fmtDate(a.date)} · ${a.time}`,time:'Сейчас'});ui.scheduleDate=a.date;setDirty('crm');closeDialog();render();if(request)requestDialog(request.id);notice('Демо-запись добавлена. Сохраните CRM, чтобы восстановить её после перезагрузки.');}
    else if(form.id==='request-form'){applyRequest(form.dataset.id,values);closeDialog();render();notice('Карточка обращения обновлена в демо.');}
    else if(form.id==='new-request-form'){const name=values.name.trim();if(!name)throw new Error('Укажите вымышленное имя.');state.crm.requests.unshift({id:`req-${Date.now()}`,name,initials:name.split(/\s+/).slice(0,2).map(s=>s[0]).join('').toUpperCase(),tone:'ice',subject:values.subject,channel:values.channel,when:'Сейчас',stage:'new',note:values.note,owner:'А. Ким',next:values.next.trim(),time:'Сегодня'});setDirty('crm');closeDialog();navigate({module:'crm',page:'requests'});notice('Демо-обращение создано.');}
    else if(form.id==='appointment-status-form'){const a=state.crm.appointments.find(a=>a.id===form.dataset.id);a.status=values.status;state.crm.log.unshift({id:`event-${Date.now()}`,name:patientById(state,a.patientId).name,text:`Статус записи: ${values.status}`,time:'Сейчас'});setDirty('crm');closeDialog();render();notice('Статус записи обновлён. Клиническая запись не изменялась.');}
    else if(form.id==='task-form'){state.tasks.push({id:`t-${Date.now()}`,text:values.text.trim(),patientId:values.patientId,time:values.time,done:false});setDirty(values.patientId);closeDialog();render();notice('Задача добавлена к демо-карте пациента.');}
  }catch(error){const target=form.querySelector('.form-error');if(target){target.textContent=error.message;target.hidden=false;}else notice(error.message);}
});
window.addEventListener('hashchange',()=>{readRoute();render();});
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&!dialog.open&&(ui.mobileQueue||ui.contextDrawer)){const selector=ui.mobileQueue?'.queue-toggle':'.context-toggle';ui.mobileQueue=false;ui.contextDrawer=false;render();document.querySelector(selector)?.focus({preventScroll:true});return;}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(!dialog.open)openSearch();}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='s'){e.preventDefault();if(dialog.open){notice('Примените изменения в окне, затем сохраните рабочее пространство.');return;}if(ui.module==='crm'){if(saveDomain('crm'))notice('CRM сохранена на устройстве.');}else if(ui.patientId&&saveDomain(ui.patientId))notice('Учебная карта сохранена на устройстве.');}});
window.addEventListener('beforeunload',e=>{if(dirty.size){e.preventDefault();e.returnValue='';}});
render();
